<?php use GreatMarketrealmCompanion\Core\Support\MarketRealmDate; defined('ABSPATH') || exit; $base=home_url('/companion/'); $root='dungeon-master/campaigns/'.$campaign->id().'/sessions'; $statusLabel=$session->status()==='in-progress'?'In Progress':ucfirst($session->status()); $duration=$session->durationSeconds(); $durationLabel=$duration>0?sprintf('%dh %02dm',intdiv($duration,3600),intdiv($duration%3600,60)):''; ?>
<section class="gmrc-session-ledger"><header class="gmrc-session-ledger__hero"><div><p class="gmrc-dm-desk__eyebrow">Session <?php echo esc_html((string)$session->number()); ?> · <?php echo esc_html($statusLabel); ?></p><h1><?php echo esc_html($session->title()); ?></h1><p><?php echo esc_html($session->scheduledDate() !== '' ? MarketRealmDate::date($session->scheduledDate()) : 'Date not yet set'); ?></p></div><?php if (! $campaign->isArchived()) : ?><a class="gmrc-session-button" href="<?php echo esc_url(add_query_arg('gmrc_route',$root.'/'.$session->id().'/edit',$base)); ?>">Edit Session</a><?php endif; ?></header>
<?php if ($session->isTabletopSession()) : ?><section class="gmrc-session-panel gmrc-session-panel--tabletop"><h2>Tabletop record</h2><p><strong>Started:</strong> <?php echo esc_html($session->startedAt() !== '' ? MarketRealmDate::dateTime($session->startedAt()) : 'Not recorded'); ?><br><strong>Ended:</strong> <?php echo esc_html($session->endedAt() !== '' ? MarketRealmDate::dateTime($session->endedAt()) : 'Session still in progress'); ?><?php if ($durationLabel !== '') : ?><br><strong>Duration:</strong> <?php echo esc_html($durationLabel); ?><?php endif; ?></p><small>Certified automatically from the linked Great MarketRealm Tabletop Session.</small></section><?php endif; ?>
<div class="gmrc-session-detail-grid"><article class="gmrc-session-panel"><h2>Dungeon Master preparation</h2><p><?php echo nl2br(esc_html($session->prepNotes() ?: 'No preparation notes were recorded.')); ?></p></article><article class="gmrc-session-panel"><h2>Session recap</h2><p><?php echo nl2br(esc_html($session->recap() ?: 'No recap has been written yet.')); ?></p></article></div>
<?php if ($session->isTabletopSession()) : ?><section class="gmrc-session-panel"><h2>Recorded contributions</h2><?php if ($session->contributions() === []) : ?><p>No character-specific deeds were recorded for this Session.</p><?php else : ?><div class="gmrc-session-contributions"><?php foreach ($session->contributions() as $row) : ?><article><strong><?php echo esc_html((string)($row['character_name'] ?? 'Adventurer')); ?></strong><p><?php $deeds=is_array($row['deeds']??null)?$row['deeds']:[]; echo esc_html($deeds!==[]?implode(' ',array_map('strval',$deeds)):'No recorded deeds during this Session.'); ?></p></article><?php endforeach; ?></div><?php endif; ?></section><?php endif; ?>
<section class="gmrc-session-panel"><h2>Attendance</h2><?php if (($attendance ?? []) === []) : ?><p>No attendance was recorded for this session.</p><?php endif; ?><div class="gmrc-session-attendance-list"><?php foreach (($attendance ?? []) as $row) : ?><article><strong><?php echo esc_html($row['user']->display_name); ?></strong><?php if (($row['characters']??[]) !== []) : ?><span><?php echo esc_html(implode(', ',array_map(static fn($character): string => $character->name()->value(),$row['characters']))); ?></span><?php endif; ?></article><?php endforeach; ?></div></section>
<p class="gmrc-session-back"><a href="<?php echo esc_url(add_query_arg('gmrc_route',$root,$base)); ?>">← Back to Session Ledger</a></p></section>
